import React, { useEffect, useMemo, useState } from "react";
import "./OptionsCalculator.css";

const CONTRACT_SIZE = 100;

const DEFAULT_INPUTS = {
  optionType: "call",
  position: "long",
  contracts: 1,
  spotPrice: 100,
  strikePrice: 105,
  premium: 4.25,
  daysToExpiry: 45,
  volatility: 30,
  riskFreeRate: 4.5,
  dividendYield: 0,
};

const OPTION_EXPLANATIONS = {
  "long-call": {
    title: "Long Call",
    view: "Bullish. You buy the right, but not the obligation, to purchase the underlying at the strike price.",
    behavior:
      "The position benefits when the underlying rises above the strike enough to cover the premium paid.",
    risk: "Maximum loss is limited to the premium paid. Upside is theoretically unlimited.",
  },
  "long-put": {
    title: "Long Put",
    view: "Bearish. You buy the right, but not the obligation, to sell the underlying at the strike price.",
    behavior:
      "The position benefits when the underlying falls below the strike enough to cover the premium paid.",
    risk: "Maximum loss is limited to the premium paid. Maximum profit is large but capped because the underlying cannot fall below zero.",
  },
  "short-call": {
    title: "Short Call",
    view: "Neutral to bearish. You sell someone else the right to buy the underlying from you at the strike price.",
    behavior:
      "The position benefits if the option expires out of the money or loses value before expiration.",
    risk: "Maximum profit is the premium received. Loss can be unlimited if the underlying rises sharply.",
  },
  "short-put": {
    title: "Short Put",
    view: "Neutral to bullish. You sell someone else the right to sell the underlying to you at the strike price.",
    behavior:
      "The position benefits if the option expires out of the money or loses value before expiration.",
    risk: "Maximum profit is the premium received. Loss can be substantial if the underlying falls, but is capped near the strike less premium.",
  },
};

function normalPdf(x) {
  return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
}

function erf(x) {
  const sign = x < 0 ? -1 : 1;
  const value = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * value);
  const a1 = 0.254829592;
  const a2 = -0.284496736;
  const a3 = 1.421413741;
  const a4 = -1.453152027;
  const a5 = 1.061405429;
  const y =
    1 -
    ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) *
      t *
      Math.exp(-value * value);

  return sign * y;
}

function normalCdf(x) {
  return 0.5 * (1 + erf(x / Math.sqrt(2)));
}

function clampNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function formatCurrency(value, maximumFractionDigits = 2) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits,
  }).format(value);
}

function formatNumber(value, maximumFractionDigits = 2) {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits,
  }).format(value);
}

function calculateBlackScholes(inputs) {
  const spot = Math.max(clampNumber(inputs.spotPrice), 0);
  const strike = Math.max(clampNumber(inputs.strikePrice), 0);
  const days = Math.max(clampNumber(inputs.daysToExpiry), 0);
  const time = days / 365;
  const volatility = Math.max(clampNumber(inputs.volatility) / 100, 0);
  const riskFreeRate = clampNumber(inputs.riskFreeRate) / 100;
  const dividendYield = clampNumber(inputs.dividendYield) / 100;

  const intrinsic =
    inputs.optionType === "call"
      ? Math.max(spot - strike, 0)
      : Math.max(strike - spot, 0);

  if (spot <= 0 || strike <= 0 || time <= 0 || volatility <= 0) {
    return {
      theoreticalPrice: intrinsic,
      intrinsic,
      timeValue: 0,
      delta:
        inputs.optionType === "call"
          ? spot > strike
            ? 1
            : 0
          : spot < strike
            ? -1
            : 0,
      gamma: 0,
      theta: 0,
      vega: 0,
      d1: null,
      d2: null,
    };
  }

  const sqrtTime = Math.sqrt(time);
  const d1 =
    (Math.log(spot / strike) +
      (riskFreeRate - dividendYield + 0.5 * volatility * volatility) * time) /
    (volatility * sqrtTime);
  const d2 = d1 - volatility * sqrtTime;
  const discountedSpot = spot * Math.exp(-dividendYield * time);
  const discountedStrike = strike * Math.exp(-riskFreeRate * time);

  const callPrice =
    discountedSpot * normalCdf(d1) - discountedStrike * normalCdf(d2);
  const putPrice =
    discountedStrike * normalCdf(-d2) - discountedSpot * normalCdf(-d1);
  const theoreticalPrice = inputs.optionType === "call" ? callPrice : putPrice;
  const pdfD1 = normalPdf(d1);
  const delta =
    inputs.optionType === "call"
      ? Math.exp(-dividendYield * time) * normalCdf(d1)
      : Math.exp(-dividendYield * time) * (normalCdf(d1) - 1);
  const gamma =
    (Math.exp(-dividendYield * time) * pdfD1) / (spot * volatility * sqrtTime);
  const vega =
    (spot * Math.exp(-dividendYield * time) * pdfD1 * sqrtTime) / 100;
  const callTheta =
    (-spot * Math.exp(-dividendYield * time) * pdfD1 * volatility) /
      (2 * sqrtTime) -
    riskFreeRate * discountedStrike * normalCdf(d2) +
    dividendYield * discountedSpot * normalCdf(d1);
  const putTheta =
    (-spot * Math.exp(-dividendYield * time) * pdfD1 * volatility) /
      (2 * sqrtTime) +
    riskFreeRate * discountedStrike * normalCdf(-d2) -
    dividendYield * discountedSpot * normalCdf(-d1);
  const theta = (inputs.optionType === "call" ? callTheta : putTheta) / 365;

  return {
    theoreticalPrice: Math.max(theoreticalPrice, 0),
    intrinsic,
    timeValue: Math.max(theoreticalPrice - intrinsic, 0),
    delta,
    gamma,
    theta,
    vega,
    d1,
    d2,
  };
}

function calculateExpirationPnl(inputs, underlyingPrice) {
  const strike = Math.max(clampNumber(inputs.strikePrice), 0);
  const premium = Math.max(clampNumber(inputs.premium), 0);
  const contracts = Math.max(Math.round(clampNumber(inputs.contracts, 1)), 1);
  const multiplier = contracts * CONTRACT_SIZE;
  const payoff =
    inputs.optionType === "call"
      ? Math.max(underlyingPrice - strike, 0)
      : Math.max(strike - underlyingPrice, 0);
  const longPnl = (payoff - premium) * multiplier;

  return inputs.position === "long" ? longPnl : -longPnl;
}

function getScenarioPrices(spot, strike) {
  const anchor = Math.max(spot, strike, 1);
  const low = Math.max(0, anchor * 0.7);
  const high = anchor * 1.3;
  const step = (high - low) / 6;

  return Array.from({ length: 7 }, (_, index) => low + step * index);
}

function Metric({ label, value, tone }) {
  return (
    <div
      className={`options-app__metric ${tone ? `options-app__metric--${tone}` : ""}`}
    >
      <span className="options-app__metric-label">{label}</span>
      <strong className="options-app__metric-value">{value}</strong>
    </div>
  );
}

function OptionsCalculator() {
  const [inputs, setInputs] = useState(DEFAULT_INPUTS);

  useEffect(() => {
    document.title = "Options Calculator — Xuan Cao";
  }, []);

  const model = useMemo(() => calculateBlackScholes(inputs), [inputs]);

  const summary = useMemo(() => {
    const spot = Math.max(clampNumber(inputs.spotPrice), 0);
    const strike = Math.max(clampNumber(inputs.strikePrice), 0);
    const premium = Math.max(clampNumber(inputs.premium), 0);
    const contracts = Math.max(Math.round(clampNumber(inputs.contracts, 1)), 1);
    const multiplier = contracts * CONTRACT_SIZE;
    const direction = inputs.position === "long" ? 1 : -1;
    const currentIntrinsicPnl =
      (model.intrinsic - premium) * multiplier * direction;
    const modelValuePnl =
      (model.theoreticalPrice - premium) * multiplier * direction;
    const breakeven =
      inputs.optionType === "call" ? strike + premium : strike - premium;
    const maxLoss =
      inputs.position === "long"
        ? premium * multiplier
        : inputs.optionType === "call"
          ? Infinity
          : Math.max((strike - premium) * multiplier, 0);
    const maxProfit =
      inputs.position === "long"
        ? inputs.optionType === "call"
          ? Infinity
          : Math.max((strike - premium) * multiplier, 0)
        : premium * multiplier;

    return {
      spot,
      strike,
      premium,
      contracts,
      multiplier,
      currentIntrinsicPnl,
      modelValuePnl,
      breakeven,
      maxLoss,
      maxProfit,
    };
  }, [inputs, model]);

  const scenarios = useMemo(() => {
    return getScenarioPrices(summary.spot, summary.strike).map((price) => ({
      price,
      pnl: calculateExpirationPnl(inputs, price),
    }));
  }, [inputs, summary.spot, summary.strike]);

  const updateInput = (key, value) => {
    setInputs((current) => ({
      ...current,
      [key]: value,
    }));
  };

  const useModelPrice = () => {
    setInputs((current) => ({
      ...current,
      premium: Number(model.theoreticalPrice.toFixed(2)),
    }));
  };

  const optionName = `${inputs.position === "long" ? "Long" : "Short"} ${
    inputs.optionType === "call" ? "Call" : "Put"
  }`;
  const optionExplanation =
    OPTION_EXPLANATIONS[`${inputs.position}-${inputs.optionType}`];

  return (
    <div className="options-app">
      <div className="container container--wide">
        <header className="options-app__header fade-in">
          <div>
            <p className="section-label">Interactive tool</p>
            <h1 className="page-title">Options Profit and Loss Calculator</h1>
            <p className="page-subtitle">
              Estimate option value with Black-Scholes inputs, then compare the
              entry premium against expiration profit and loss scenarios.
            </p>
          </div>
          <div className="options-app__disclaimer" role="note">
            This calculator is for reference and education only. It is not
            financial advice, investment advice, or a recommendation to buy,
            sell, or hold any security.
          </div>
        </header>

        <section className="options-app__workspace fade-in fade-in--delay-1">
          <form className="options-app__panel" aria-label="Option assumptions">
            <div className="options-app__panel-header">
              <h2>Assumptions</h2>
              <p>{optionName}</p>
            </div>

            <div className="options-app__segmented" aria-label="Option type">
              <button
                type="button"
                className={inputs.optionType === "call" ? "is-active" : ""}
                onClick={() => updateInput("optionType", "call")}
              >
                Call
              </button>
              <button
                type="button"
                className={inputs.optionType === "put" ? "is-active" : ""}
                onClick={() => updateInput("optionType", "put")}
              >
                Put
              </button>
            </div>

            <div className="options-app__segmented" aria-label="Position">
              <button
                type="button"
                className={inputs.position === "long" ? "is-active" : ""}
                onClick={() => updateInput("position", "long")}
              >
                Long
              </button>
              <button
                type="button"
                className={inputs.position === "short" ? "is-active" : ""}
                onClick={() => updateInput("position", "short")}
              >
                Short
              </button>
            </div>

            <section className="options-app__explanation" aria-live="polite">
              <div className="options-app__explanation-header">
                <span>Selected strategy</span>
                <strong>{optionExplanation.title}</strong>
              </div>
              <p>{optionExplanation.view}</p>
              <p>{optionExplanation.behavior}</p>
              <p>{optionExplanation.risk}</p>
              <dl>
                <div>
                  <dt>Breakeven</dt>
                  <dd>{formatCurrency(summary.breakeven)}</dd>
                </div>
                <div>
                  <dt>Current max loss</dt>
                  <dd>
                    {Number.isFinite(summary.maxLoss)
                      ? formatCurrency(summary.maxLoss)
                      : "Unlimited"}
                  </dd>
                </div>
              </dl>
            </section>

            <div className="options-app__input-grid">
              <label>
                <span>Underlying price</span>
                <input
                  type="number"
                  min="0"
                  step="0.01"
                  value={inputs.spotPrice}
                  onChange={(event) =>
                    updateInput("spotPrice", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Strike price</span>
                <input
                  type="number"
                  min="0"
                  step="0.01"
                  value={inputs.strikePrice}
                  onChange={(event) =>
                    updateInput("strikePrice", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Entry premium</span>
                <input
                  type="number"
                  min="0"
                  step="0.01"
                  value={inputs.premium}
                  onChange={(event) =>
                    updateInput("premium", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Contracts</span>
                <input
                  type="number"
                  min="1"
                  step="1"
                  value={inputs.contracts}
                  onChange={(event) =>
                    updateInput("contracts", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Days to expiration</span>
                <input
                  type="number"
                  min="0"
                  step="1"
                  value={inputs.daysToExpiry}
                  onChange={(event) =>
                    updateInput("daysToExpiry", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Volatility (%)</span>
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  value={inputs.volatility}
                  onChange={(event) =>
                    updateInput("volatility", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Risk-free rate (%)</span>
                <input
                  type="number"
                  step="0.1"
                  value={inputs.riskFreeRate}
                  onChange={(event) =>
                    updateInput("riskFreeRate", event.target.value)
                  }
                />
              </label>
              <label>
                <span>Dividend yield (%)</span>
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  value={inputs.dividendYield}
                  onChange={(event) =>
                    updateInput("dividendYield", event.target.value)
                  }
                />
              </label>
            </div>
          </form>

          <div className="options-app__results">
            <section className="options-app__panel">
              <div className="options-app__panel-header">
                <h2>Model Price</h2>
                <button type="button" onClick={useModelPrice}>
                  Use as premium
                </button>
              </div>
              <div className="options-app__hero-number">
                {formatCurrency(model.theoreticalPrice)}
                <span>Black-Scholes fair value per share</span>
              </div>
              <div className="options-app__metrics">
                <Metric
                  label="Intrinsic value"
                  value={formatCurrency(model.intrinsic)}
                />
                <Metric
                  label="Time value"
                  value={formatCurrency(model.timeValue)}
                />
                <Metric
                  label="Model P/L now"
                  value={formatCurrency(summary.modelValuePnl)}
                  tone={summary.modelValuePnl >= 0 ? "positive" : "negative"}
                />
                <Metric
                  label="Expiration breakeven"
                  value={formatCurrency(summary.breakeven)}
                />
              </div>
            </section>

            <section className="options-app__panel">
              <div className="options-app__panel-header">
                <h2>Risk Profile</h2>
                <p>{summary.contracts} contract(s), 100 shares each</p>
              </div>
              <div className="options-app__metrics options-app__metrics--three">
                <Metric
                  label="Max profit"
                  value={
                    Number.isFinite(summary.maxProfit)
                      ? formatCurrency(summary.maxProfit)
                      : "Unlimited"
                  }
                  tone="positive"
                />
                <Metric
                  label="Max loss"
                  value={
                    Number.isFinite(summary.maxLoss)
                      ? formatCurrency(summary.maxLoss)
                      : "Unlimited"
                  }
                  tone="negative"
                />
                <Metric
                  label="Intrinsic P/L now"
                  value={formatCurrency(summary.currentIntrinsicPnl)}
                  tone={
                    summary.currentIntrinsicPnl >= 0 ? "positive" : "negative"
                  }
                />
              </div>
            </section>

            <section className="options-app__panel">
              <div className="options-app__panel-header">
                <h2>Greeks</h2>
                <p>Approximate sensitivity per share</p>
              </div>
              <div className="options-app__greeks">
                <Metric label="Delta" value={formatNumber(model.delta, 4)} />
                <Metric label="Gamma" value={formatNumber(model.gamma, 4)} />
                <Metric
                  label="Theta / day"
                  value={formatCurrency(model.theta, 4)}
                />
                <Metric
                  label="Vega / 1%"
                  value={formatCurrency(model.vega, 4)}
                />
              </div>
            </section>
          </div>
        </section>

        <section className="options-app__panel options-app__table-panel fade-in fade-in--delay-2">
          <div className="options-app__panel-header">
            <h2>Expiration Scenarios</h2>
            <p>Profit and loss at different underlying prices</p>
          </div>
          <div className="options-app__table-wrap">
            <table className="options-app__table">
              <thead>
                <tr>
                  <th>Underlying at expiration</th>
                  <th>Option payoff</th>
                  <th>Total P/L</th>
                </tr>
              </thead>
              <tbody>
                {scenarios.map((scenario) => {
                  const payoff =
                    inputs.optionType === "call"
                      ? Math.max(scenario.price - summary.strike, 0)
                      : Math.max(summary.strike - scenario.price, 0);

                  return (
                    <tr key={scenario.price}>
                      <td>{formatCurrency(scenario.price)}</td>
                      <td>{formatCurrency(payoff)}</td>
                      <td
                        className={
                          scenario.pnl >= 0
                            ? "options-app__positive"
                            : "options-app__negative"
                        }
                      >
                        {formatCurrency(scenario.pnl)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </section>
      </div>
    </div>
  );
}

export default OptionsCalculator;
