import React, { useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import "./Secret.css";

function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  }
  return bytes;
}

async function decryptHtml(encData, password) {
  const salt = hexToBytes(encData.salt);
  const iv = hexToBytes(encData.iv);
  const ciphertextWithTag = hexToBytes(encData.ciphertext);

  const keyMaterial = await window.crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  const key = await window.crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["decrypt"]
  );

  const decrypted = await window.crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ciphertextWithTag
  );

  return new TextDecoder().decode(decrypted);
}

function Secret() {
  const [searchParams] = useSearchParams();
  const htmlRef = useRef(null);
  const [payload, setPayload] = useState(null);
  const [html, setHtml] = useState("");
  const [manualKey, setManualKey] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [decryptError, setDecryptError] = useState(false);

  const handleDecrypt = useCallback(async (data, key) => {
    try {
      const decryptedHtml = await decryptHtml(data, key);
      setHtml(decryptedHtml);
      setDecryptError(false);
      document.title = `${data.title} — Xuan Cao`;
    } catch (error) {
      console.error("Secret posts decryption failed:", error);
      setHtml("");
      setDecryptError(true);
    }
  }, []);

  useEffect(() => {
    document.title = "Secret — Xuan Cao";
    const key = searchParams.get("key");

    fetch(`${process.env.PUBLIC_URL}/secret/posts.json`)
      .then((response) => {
        if (!response.ok) throw new Error("Secret posts not found");
        return response.json();
      })
      .then(async (data) => {
        setPayload(data);
        setLoading(false);

        if (key) {
          await handleDecrypt(data, key);
        }
      })
      .catch((error) => {
        console.error("Failed to load secret posts:", error);
        setLoadError(true);
        setLoading(false);
      });
  }, [searchParams, handleDecrypt]);

  useEffect(() => {
    if (!html || !htmlRef.current) return undefined;

    const root = htmlRef.current;
    const search = root.querySelector("[data-secret-search]");
    const posts = Array.from(root.querySelectorAll("[data-secret-post]"));
    const count = root.querySelector("[data-secret-count]");
    const empty = root.querySelector("[data-secret-empty]");

    if (!search) return undefined;

    const renderSearch = () => {
      const query = search.value.trim().toLowerCase();
      let visibleCount = 0;

      posts.forEach((post) => {
        const title = post.dataset.secretTitle || "";
        const matches = !query || title.includes(query);
        post.hidden = !matches;
        if (matches) visibleCount += 1;
      });

      if (count) {
        count.textContent = `${visibleCount} secret post${
          visibleCount === 1 ? "" : "s"
        }`;
      }

      if (empty) {
        empty.hidden = visibleCount > 0;
      }
    };

    search.addEventListener("input", renderSearch);
    renderSearch();

    return () => {
      search.removeEventListener("input", renderSearch);
    };
  }, [html]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!payload || !manualKey.trim()) return;
    await handleDecrypt(payload, manualKey.trim());
  };

  if (loading) {
    return (
      <div className="secret-page">
        <div className="container container--prose">
          <p className="secret-page__message">Loading…</p>
        </div>
      </div>
    );
  }

  if (loadError || !payload) {
    return (
      <div className="secret-page">
        <div className="container container--prose">
          <p className="secret-page__message">Secret posts not found.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="secret-page">
      <div className="container container--prose">
        <header className="secret-page__header fade-in">
          <p className="section-label">Encrypted posts</p>
          <h1 className="page-title">{payload.title}</h1>
          <p className="page-subtitle">
            Enter the key to decrypt the private post archive and render it as
            normal HTML.
          </p>
        </header>

        {!html ? (
          <section className="secret-page__locked fade-in fade-in--delay-1">
            <div className="secret-page__lock-icon">Locked</div>
            <form className="secret-page__form" onSubmit={handleSubmit}>
              <input
                type="password"
                value={manualKey}
                placeholder="Enter decryption key"
                onChange={(event) => {
                  setManualKey(event.target.value);
                  setDecryptError(false);
                }}
                autoFocus
              />
              <button type="submit">Decrypt</button>
            </form>
            {decryptError && (
              <p className="secret-page__error">
                Incorrect key. Please try again.
              </p>
            )}
          </section>
        ) : (
          <section className="secret-page__unlocked fade-in fade-in--delay-1">
            <div
              ref={htmlRef}
              className="secret-page__html"
              dangerouslySetInnerHTML={{ __html: html }}
            />
          </section>
        )}
      </div>
    </div>
  );
}

export default Secret;
