import React, { useEffect, useMemo, useState } from "react";
import "./TextCompare.css";

const SAMPLE_LEFT = `Design systems keep interfaces consistent.
Small controls should feel predictable.
A good tool respects private text.`;

const SAMPLE_RIGHT = `Design systems keep products consistent.
Small controls should feel fast and predictable.
A good tool keeps private text in your browser.`;

const DEFAULT_EDITOR_HEIGHT = 320;
const MIN_EDITOR_HEIGHT = 220;

const splitLines = (value) => value.replace(/\r\n/g, "\n").split("\n");

function normalizeText(value, options) {
  let normalized = value.replace(/\r\n/g, "\n");

  if (options.lineBreaksToSpaces) {
    normalized = normalized.replace(/\n+/g, " ");
  }

  if (options.collapseWhitespace) {
    normalized = normalized
      .split("\n")
      .map((line) => line.trim().replace(/\s+/g, " "))
      .join("\n");
  }

  if (options.ignoreCase) {
    normalized = normalized.toLowerCase();
  }

  if (options.sortLines) {
    normalized = splitLines(normalized)
      .sort((a, b) => a.localeCompare(b))
      .join("\n");
  }

  return normalized;
}

function buildRawDiff(leftLines, rightLines) {
  const leftLength = leftLines.length;
  const rightLength = rightLines.length;
  const matrix = Array.from(
    { length: leftLength + 1 },
    () => new Uint32Array(rightLength + 1)
  );

  for (let i = 1; i <= leftLength; i += 1) {
    for (let j = 1; j <= rightLength; j += 1) {
      if (leftLines[i - 1] === rightLines[j - 1]) {
        matrix[i][j] = matrix[i - 1][j - 1] + 1;
      } else {
        matrix[i][j] = Math.max(matrix[i - 1][j], matrix[i][j - 1]);
      }
    }
  }

  const operations = [];
  let i = leftLength;
  let j = rightLength;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && leftLines[i - 1] === rightLines[j - 1]) {
      operations.push({
        type: "equal",
        left: leftLines[i - 1],
        right: rightLines[j - 1],
        leftLine: i,
        rightLine: j,
      });
      i -= 1;
      j -= 1;
    } else if (j > 0 && (i === 0 || matrix[i][j - 1] > matrix[i - 1][j])) {
      operations.push({
        type: "insert",
        left: "",
        right: rightLines[j - 1],
        leftLine: null,
        rightLine: j,
      });
      j -= 1;
    } else {
      operations.push({
        type: "delete",
        left: leftLines[i - 1],
        right: "",
        leftLine: i,
        rightLine: null,
      });
      i -= 1;
    }
  }

  return operations.reverse();
}

function combineChanges(operations) {
  const rows = [];
  let index = 0;

  while (index < operations.length) {
    const operation = operations[index];

    if (operation.type === "equal") {
      rows.push(operation);
      index += 1;
      continue;
    }

    const firstType = operation.type;
    const secondType = firstType === "delete" ? "insert" : "delete";
    const firstRun = [];
    const secondRun = [];

    while (operations[index] && operations[index].type === firstType) {
      firstRun.push(operations[index]);
      index += 1;
    }

    while (operations[index] && operations[index].type === secondType) {
      secondRun.push(operations[index]);
      index += 1;
    }

    const deletes = firstType === "delete" ? firstRun : secondRun;
    const inserts = firstType === "insert" ? firstRun : secondRun;

    const pairedLength = Math.max(deletes.length, inserts.length);
    for (let pairIndex = 0; pairIndex < pairedLength; pairIndex += 1) {
      const deleted = deletes[pairIndex];
      const inserted = inserts[pairIndex];

      if (deleted && inserted) {
        rows.push({
          type: "change",
          left: deleted.left,
          right: inserted.right,
          leftLine: deleted.leftLine,
          rightLine: inserted.rightLine,
        });
      } else if (deleted) {
        rows.push(deleted);
      } else if (inserted) {
        rows.push(inserted);
      }
    }
  }

  return rows;
}

function buildLineDiff(leftText, rightText) {
  const leftLines = splitLines(leftText);
  const rightLines = splitLines(rightText);
  return combineChanges(buildRawDiff(leftLines, rightLines));
}

function splitCharacters(value) {
  if (typeof Intl !== "undefined" && Intl.Segmenter) {
    return Array.from(
      new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(value),
      (segment) => segment.segment
    );
  }

  return Array.from(value);
}

function tokenize(value, detailMode) {
  if (detailMode === "character") {
    return splitCharacters(value);
  }

  return value.match(/\s+|[^\s]+/g) || [];
}

function buildTokenDiff(leftText, rightText, detailMode) {
  const leftTokens = tokenize(leftText, detailMode);
  const rightTokens = tokenize(rightText, detailMode);
  const operations = buildRawDiff(leftTokens, rightTokens);

  return operations.map((operation, index) => ({
    key: `${operation.type}-${index}`,
    type: operation.type,
    text:
      operation.type === "insert"
        ? operation.right
        : operation.type === "delete"
          ? operation.left
          : operation.left,
  }));
}

function renderLineContent(row, side, detailMode) {
  if (row.type !== "change") {
    return side === "left" ? row.left : row.right;
  }

  const tokenDiff = buildTokenDiff(row.left, row.right, detailMode);
  const visibleTypes =
    side === "left"
      ? new Set(["equal", "delete"])
      : new Set(["equal", "insert"]);

  return tokenDiff
    .filter((token) => visibleTypes.has(token.type))
    .map((token) => (
      <span
        key={token.key}
        className={`text-compare__token text-compare__token--${token.type}`}
      >
        {token.text}
      </span>
    ));
}

function TextCompare() {
  const [leftText, setLeftText] = useState(SAMPLE_LEFT);
  const [rightText, setRightText] = useState(SAMPLE_RIGHT);
  const [options, setOptions] = useState({
    ignoreCase: false,
    sortLines: false,
    lineBreaksToSpaces: false,
    collapseWhitespace: false,
  });
  const [detailMode, setDetailMode] = useState("word");
  const [copied, setCopied] = useState(false);
  const [editorHeight, setEditorHeight] = useState(DEFAULT_EDITOR_HEIGHT);

  useEffect(() => {
    document.title = "Text Compare — Xuan Cao";
  }, []);

  const comparison = useMemo(() => {
    const normalizedLeft = normalizeText(leftText, options);
    const normalizedRight = normalizeText(rightText, options);
    const rows = buildLineDiff(normalizedLeft, normalizedRight);
    const additions = rows.filter((row) => row.type === "insert").length;
    const deletions = rows.filter((row) => row.type === "delete").length;
    const changes = rows.filter((row) => row.type === "change").length;
    const unchanged = rows.filter((row) => row.type === "equal").length;

    return {
      rows,
      additions,
      deletions,
      changes,
      unchanged,
      identical: normalizedLeft === normalizedRight,
      leftLines: splitLines(normalizedLeft).length,
      rightLines: splitLines(normalizedRight).length,
    };
  }, [leftText, options, rightText]);

  const toggleOption = (key) => {
    setOptions((current) => ({
      ...current,
      [key]: !current[key],
    }));
    setCopied(false);
  };

  const switchTexts = () => {
    setLeftText(rightText);
    setRightText(leftText);
    setCopied(false);
  };

  const clearAll = () => {
    setLeftText("");
    setRightText("");
    setCopied(false);
  };

  const resetSample = () => {
    setLeftText(SAMPLE_LEFT);
    setRightText(SAMPLE_RIGHT);
    setCopied(false);
  };

  const startEditorResize = (event) => {
    event.preventDefault();

    const startY = event.clientY;
    const startHeight = editorHeight;
    const originalUserSelect = document.body.style.userSelect;

    document.body.style.userSelect = "none";

    const resize = (moveEvent) => {
      const nextHeight = startHeight + moveEvent.clientY - startY;
      setEditorHeight(Math.max(MIN_EDITOR_HEIGHT, nextHeight));
    };

    const stopResize = () => {
      document.body.style.userSelect = originalUserSelect;
      window.removeEventListener("pointermove", resize);
      window.removeEventListener("pointerup", stopResize);
      window.removeEventListener("pointercancel", stopResize);
    };

    window.addEventListener("pointermove", resize);
    window.addEventListener("pointerup", stopResize);
    window.addEventListener("pointercancel", stopResize);
  };

  const copyDiff = async () => {
    const output = comparison.rows
      .flatMap((row) => {
        if (row.type === "equal") return [`  ${row.left}`];
        if (row.type === "insert") return [`+ ${row.right}`];
        if (row.type === "delete") return [`- ${row.left}`];
        return [`- ${row.left}`, `+ ${row.right}`];
      })
      .join("\n");

    try {
      await navigator.clipboard.writeText(output);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch (error) {
      setCopied(false);
    }
  };

  return (
    <div className="text-compare">
      <div className="container container--wide">
        <header className="text-compare__header fade-in">
          <div>
            <p className="section-label">Interactive tool</p>
            <h1 className="page-title">Text Compare</h1>
            <p className="page-subtitle">
              Compare two drafts, snippets, configs, or notes with local
              line-by-line and inline differences.
            </p>
          </div>
          <div
            className={`text-compare__status ${
              comparison.identical
                ? "text-compare__status--match"
                : "text-compare__status--diff"
            }`}
            role="status"
          >
            <strong>
              {comparison.identical ? "Texts match" : "Differences found"}
            </strong>
            <span>
              {comparison.changes + comparison.additions + comparison.deletions}{" "}
              changed rows
            </span>
          </div>
        </header>

        <section className="text-compare__toolbar fade-in fade-in--delay-1">
          <div
            className="text-compare__segmented"
            aria-label="Inline diff detail"
          >
            {[
              ["word", "Word"],
              ["character", "Character"],
            ].map(([mode, label]) => (
              <button
                key={mode}
                type="button"
                className={detailMode === mode ? "is-active" : ""}
                onClick={() => setDetailMode(mode)}
              >
                {label}
              </button>
            ))}
          </div>

          <div
            className="text-compare__toggles"
            aria-label="Comparison options"
          >
            <label>
              <input
                type="checkbox"
                checked={options.ignoreCase}
                onChange={() => toggleOption("ignoreCase")}
              />
              <span>To lowercase</span>
            </label>
            <label>
              <input
                type="checkbox"
                checked={options.sortLines}
                onChange={() => toggleOption("sortLines")}
              />
              <span>Sort lines</span>
            </label>
            <label>
              <input
                type="checkbox"
                checked={options.lineBreaksToSpaces}
                onChange={() => toggleOption("lineBreaksToSpaces")}
              />
              <span>Line breaks to spaces</span>
            </label>
            <label>
              <input
                type="checkbox"
                checked={options.collapseWhitespace}
                onChange={() => toggleOption("collapseWhitespace")}
              />
              <span>Remove excess white space</span>
            </label>
          </div>

          <div className="text-compare__actions">
            <button type="button" onClick={switchTexts}>
              Switch
            </button>
            <button type="button" onClick={copyDiff}>
              {copied ? "Copied" : "Copy diff"}
            </button>
            <button type="button" onClick={resetSample}>
              Sample
            </button>
            <button type="button" onClick={clearAll}>
              Clear
            </button>
          </div>
        </section>

        <section className="text-compare__editors fade-in fade-in--delay-2">
          <div className="text-compare__panel">
            <div className="text-compare__panel-header">
              <h2>Original</h2>
              <p>{comparison.leftLines.toLocaleString()} lines</p>
            </div>
            <textarea
              style={{ height: `${editorHeight}px` }}
              value={leftText}
              onChange={(event) => {
                setLeftText(event.target.value);
                setCopied(false);
              }}
              spellCheck="false"
              aria-label="Original text"
            />
            <button
              type="button"
              className="text-compare__resize-handle"
              onPointerDown={startEditorResize}
              aria-label="Resize text editors"
            />
          </div>

          <div className="text-compare__panel">
            <div className="text-compare__panel-header">
              <h2>Changed</h2>
              <p>{comparison.rightLines.toLocaleString()} lines</p>
            </div>
            <textarea
              style={{ height: `${editorHeight}px` }}
              value={rightText}
              onChange={(event) => {
                setRightText(event.target.value);
                setCopied(false);
              }}
              spellCheck="false"
              aria-label="Changed text"
            />
            <button
              type="button"
              className="text-compare__resize-handle"
              onPointerDown={startEditorResize}
              aria-label="Resize text editors"
            />
          </div>
        </section>

        <section
          className="text-compare__diff fade-in fade-in--delay-3"
          aria-label="Text differences"
        >
          <div className="text-compare__diff-header">
            <span>Original</span>
            <span>Changed</span>
          </div>
          <div className="text-compare__diff-body">
            {comparison.rows.map((row, index) => (
              <div
                key={`${row.type}-${row.leftLine || "x"}-${row.rightLine || "x"}-${index}`}
                className={`text-compare__row text-compare__row--${row.type}`}
              >
                <div className="text-compare__line-number">
                  {row.leftLine || ""}
                </div>
                <pre>{renderLineContent(row, "left", detailMode)}</pre>
                <div className="text-compare__line-number">
                  {row.rightLine || ""}
                </div>
                <pre>{renderLineContent(row, "right", detailMode)}</pre>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}

export default TextCompare;
