import React, { useState, useEffect } from "react";
import BlogCard from "../../components/BlogCard/BlogCard";
import "./Blog.css";

function Blog() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    document.title = "Writing — Xuan Cao";

    fetch(`${process.env.PUBLIC_URL}/posts-manifest.json`)
      .then((res) => res.json())
      .then((data) => {
        setPosts(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to load posts:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div className="blog-page">
      <div className="container container--prose">
        <header className="blog-page__header fade-in" id="blog-header">
          <h1 className="page-title">Writing</h1>
          <p className="page-subtitle">
            Thoughts on everything.
          </p>
        </header>

        <hr className="divider" />

        <section className="blog-page__list fade-in fade-in--delay-1" id="blog-list">
          {loading ? (
            <p className="blog-page__loading">Loading…</p>
          ) : posts.length === 0 ? (
            <p className="blog-page__empty">No posts yet.</p>
          ) : (
            posts.map((post) => <BlogCard key={post.slug} post={post} />)
          )}
        </section>
      </div>
    </div>
  );
}

export default Blog;
